def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    chairs = image_patch.find("chair")
    tables = image_patch.find("table")
    windows = image_patch.find("window")

    if not chairs or not tables or not windows:
        return image_patch

    # Find the table next to the window
    table_next_to_window = None
    for table in tables:
        for window in windows:
            if abs(table.horizontal_center - window.horizontal_center) < 100:
                table_next_to_window = table
                break
        if table_next_to_window:
            break

    if not table_next_to_window:
        return image_patch

    # Find the chair at the table next to the window
    chair_at_table = None
    for chair in chairs:
        if abs(chair.horizontal_center - table_next_to_window.horizontal_center) < 100:
            chair_at_table = chair
            break

    if not chair_at_table:
        return image_patch

    # Find the back of the chair
    back_of_chair = None
    for part in chair_at_table.cropped_image:
        if part == "back":
            back_of_chair = part
            break

    if not back_of_chair:
        return image_patch

    return back_of_chair

